// ⚙️ CONFIG — the only node you need to edit.
const config = {
  // Your Jira Cloud site. Must match the Jira credential.
  jiraBaseUrl: 'https://your-company.atlassian.net',

  // Which bug reports to check. Keep the label filter: it stops a ticket being checked twice.
  jql: 'project = BUG AND issuetype = Bug AND status = "Triage" AND (labels is EMPTY OR labels not in (ai-repro-checked, ai-needs-human)) ORDER BY created ASC',
  maxIssuesPerRun: 10,

  // Who gets tagged in the comment: 'reporter', or the id of a user-picker custom field
  // (e.g. 'customfield_10050') if tickets are created by a service account for someone else.
  requesterField: 'reporter',

  // Status for unclear bugs. Use the status NAME as shown on your board. '' = don't move.
  waitingForInfoStatus: 'Waiting for info',

  labels: {
    checked: 'ai-repro-checked',   // added to every ticket the AI checked
    needsHuman: 'ai-needs-human',  // added when the model's answer was not usable
  },

  model: 'gpt-5.4-mini',
};

// Manual test on one ticket: set a key here, then press "Test workflow". Ignored on scheduled runs.
const testIssueKey = '';
config.searchJql = $('▶ Test run').isExecuted && testIssueKey ? `key = ${testIssueKey}` : config.jql;
return [{ json: config }];

// ---- helpers ----
function adfToText(node) {
  // Jira Cloud (API v3) returns rich text as ADF. This turns it into plain text an LLM can read.
  if (node == null) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(adfToText).join('');
  switch (node.type) {
    case 'text': {
      const link = (node.marks || []).find((m) => m.type === 'link');
      const href = link?.attrs?.href;
      return href && href !== node.text ? `${node.text} (${href})` : (node.text || '');
    }
    case 'hardBreak': return '\n';
    case 'mention': return node.attrs?.text || '@user';
    case 'emoji': return node.attrs?.text || '';
    case 'inlineCard':
    case 'blockCard': return node.attrs?.url || '';
    case 'media': return '[attachment]';
    case 'paragraph':
    case 'heading': return adfToText(node.content) + '\n';
    case 'listItem': return '- ' + adfToText(node.content).trim() + '\n';
    case 'bulletList':
    case 'orderedList': return adfToText(node.content) + '\n';
    case 'tableRow': return '| ' + (node.content || []).map((c) => adfToText(c.content).trim().replace(/\n+/g, ' ')).join(' | ') + ' |\n';
    case 'codeBlock': return '```\n' + adfToText(node.content) + '\n```\n';
    case 'rule': return '---\n';
    default: return adfToText(node.content);
  }
}

function personFrom(value) {
  // Works for the reporter field and for single or multi user-picker custom fields.
  const p = Array.isArray(value) ? value[0] : value;
  return { accountId: p?.accountId || '', name: p?.displayName || '' };
}
// ---- end helpers ----

const cfg = $('⚙️ Config').first().json;
const issues = $input.first().json.issues || [];
return issues.map((issue) => {
  const f = issue.fields || {};
  const requester = personFrom(f[cfg.requesterField] ?? f.reporter);
  return {
    json: {
      key: issue.key,
      summary: f.summary || '',
      description: adfToText(f.description).trim(),
      requesterAccountId: requester.accountId,
      requesterName: requester.name,
    },
  };
});

// ---- helpers ----
function getLlmText(json) {
  // Works with the OpenAI "Message a model" node and most other model nodes.
  if (typeof json?.output === 'string') return json.output;
  if (Array.isArray(json?.output)) {
    for (const part of json.output) {
      if (Array.isArray(part?.content)) {
        const t = part.content.find((c) => c?.text != null);
        if (t) return typeof t.text === 'string' ? t.text : JSON.stringify(t.text); // JSON output mode returns an object
      }
    }
  }
  if (typeof json?.text === 'string') return json.text;
  if (typeof json?.content === 'string') return json.content;
  if (Array.isArray(json?.content)) {
    // Anthropic and similar: the text can come after a "thinking" block
    const t = json.content.find((c) => c?.type === 'text' && typeof c.text === 'string');
    if (t) return t.text;
  }
  if (typeof json?.merged_response === 'string' && json.merged_response) return json.merged_response;
  if (typeof json?.message?.content === 'string') return json.message.content;
  if (typeof json?.choices?.[0]?.message?.content === 'string') return json.choices[0].message.content;
  throw new Error('Could not find the text in the model response. Check the model node output.');
}

function parseLlmJson(text) {
  // Returns the parsed object, or null if the model did not return valid JSON.
  const cleaned = String(text ?? '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  try { return JSON.parse(cleaned); } catch (e) { /* try the first {...} block */ }
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try { return JSON.parse(match[0]); } catch (e) { return null; }
}
// ---- end helpers ----

// Never trust the model blindly: anything that is not the agreed JSON goes to a human.
const cfg = $('⚙️ Config').first().json;
const ticket = $('One item per bug').item.json;
const raw = getLlmText($json);
const ai = parseLlmJson(raw);
const message = String(ai?.message ?? '').trim();

let verdict = 'invalid';
if (ai && ai.reproducible === true) verdict = 'clear';
else if (ai && ai.reproducible === false && message) verdict = 'unclear';

return {
  json: {
    ...ticket,
    verdict,
    message,
    labelToAdd: verdict === 'invalid' ? cfg.labels.needsHuman : cfg.labels.checked,
    ...(verdict === 'invalid' ? { modelOutput: raw.slice(0, 500) } : {}),
  },
};

// Finds the transition that leads to the configured status NAME.
const key = $('Read AI verdict').item.json.key;
const target = String($('⚙️ Config').first().json.waitingForInfoStatus).trim();
const list = $json.transitions || [];
const hit = list.find((t) => (t.to?.name || '').toLowerCase() === target.toLowerCase())
  || list.find((t) => (t.name || '').toLowerCase() === target.toLowerCase());
if (!hit) {
  const reachable = list.map((t) => t.to?.name).filter(Boolean).join(', ') || 'none';
  throw new Error(`Can't move ${key} to "${target}": not reachable from its current status (reachable: ${reachable}). Check the status name in ⚙️ Config.`);
}
return { json: { key, transitionId: hit.id, status: hit.to?.name || target } };
